// Paste the Slack incoming-webhook URL for the channel these should land in.
const SLACK_WEBHOOK = '';
// Counts only - no client names, no content.
const r = $input.first().json;
const healthy = Number(r.runs_24h) > 0 && Number(r.stuck) === 0 && Number(r.failed) === 0;
const d = r.latest_call ? new Date(r.latest_call) : null;
const nice = d ? d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' }) : 'none yet';
const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: healthy
      ? ':brain: *tnAI · Daily health check*  :large_green_circle:'
      : ':brain: *tnAI · Daily health check*  :warning: *needs a look*' } },
  { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Calls ingested*\n' + r.calls_24h + ' in the last 24h' },
      { type: 'mrkdwn', text: '*Signals extracted*\n' + r.signals_24h + ' in the last 24h' },
      { type: 'mrkdwn', text: '*Latest call*\n' + nice },
      { type: 'mrkdwn', text: '*Queue*\n' + (Number(r.queue_pending) || 0) + ' waiting' },
    ] },
];
if (!healthy) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: ' +
  (Number(r.stuck) ? r.stuck + ' item(s) stuck mid-pipeline. ' : '') +
  (Number(r.failed) ? r.failed + ' item(s) failed in the last 24h. ' : '') +
  (Number(r.runs_24h) === 0 ? 'No pipeline runs recorded in 24h. ' : '') } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'All pipelines monitored · counts only, no client data · <https://ast.tecknuovo.com|open the dashboard>' }] });
const line = healthy
  ? 'tnAI healthy · ' + r.calls_24h + ' calls and ' + r.signals_24h + ' signals in 24h'
  : 'tnAI needs a look · stuck: ' + r.stuck + ' · failed: ' + r.failed;
// Dead-man's switch: paste a healthchecks.io ping URL here.
const PING_URL = '';
return [{ json: { webhook: SLACK_WEBHOOK, line, blocks, healthy, ping: PING_URL ? (healthy ? PING_URL : PING_URL + '/fail') : null } }];
